use gpui_kit::*;

/// Side of the logo's pixel grid, also its size in logical pixels.
pub const SIZE: usize = 32;

/// The logo grid as straight-alpha RGBA, one byte quad per cell. Generated by tools/make_icon.py.
pub static RGBA: &[u8] = include_bytes!("../../../assets/icon/nebucat-32.rgba");

/// The pixel logo, drawn as one quad per same-colored run of cells.
pub fn element() -> impl IntoElement {
    canvas(|_, _, _| (), |bounds, (), window, _| paint(bounds, window))
        .size(px(SIZE as f32))
        .flex_none()
}

fn cell(x: usize, y: usize) -> &'static [u8] {
    let i = (y * SIZE + x) * 4;
    &RGBA[i..i + 4]
}

fn paint(bounds: Bounds<Pixels>, window: &mut Window) {
    // Cell edges land on whole device pixels, so cells stay sharp at fractional scale factors.
    let scale = window.scale_factor();
    let left = (f32::from(bounds.origin.x) * scale).round();
    let top = (f32::from(bounds.origin.y) * scale).round();
    let span = (SIZE as f32 * scale).round();
    let edge = |i: usize| (i as f32 * span / SIZE as f32).round();
    let logical = |device: f32| px(device / scale);

    for y in 0..SIZE {
        let mut x = 0;
        while x < SIZE {
            let color = cell(x, y);
            let start = x;
            while x < SIZE && cell(x, y) == color {
                x += 1;
            }
            if color[3] == 0 {
                continue;
            }
            let quad = Bounds::from_corners(
                point(logical(left + edge(start)), logical(top + edge(y))),
                point(logical(left + edge(x)), logical(top + edge(y + 1))),
            );
            let fill_color = Rgba {
                r: f32::from(color[0]) / 255.,
                g: f32::from(color[1]) / 255.,
                b: f32::from(color[2]) / 255.,
                a: f32::from(color[3]) / 255.,
            };
            window.paint_quad(fill(quad, fill_color));
        }
    }
}
